using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var searchTool = AIFunctionFactory.Create(SearchWeb);
var addNoteTool = AIFunctionFactory.Create(notebook.AddNote);
var readNotesTool = AIFunctionFactory.Create(notebook.ReadNotes);

// ---------------------------------------------------------------------------
// Chat client with tool support
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool],
    Temperature = 0.2f,
};

// ---------------------------------------------------------------------------
// Prompt the user for a research topic
// ---------------------------------------------------------------------------
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided – exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching \"{topic}\" …\n");

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
List<ChatMessage> history =
[
    new(ChatRole.System, """
        You are a research assistant. The user will give you a topic.
        1. Use the SearchWeb tool to find relevant information (make several
           searches with different queries to get broad coverage).
        2. Use the AddNote tool to save every important finding as a note.
        3. After you have gathered enough information, use ReadNotes to review
           your notes, then produce a well-structured summary for the user.
        Be thorough but concise. Cite sources when possible.
        """),
    new(ChatRole.User, $"Please research the following topic and summarize your findings:\n\n{topic}"),
];

var response = await client.GetResponseAsync(history, chatOptions);
Console.WriteLine(response.Text);

// ---------------------------------------------------------------------------
// Tool implementations
// ---------------------------------------------------------------------------

/// <summary>Searches the web for the given query and returns result snippets.</summary>
[Description("Search the web for a query and return result snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query string")] string query)
{
    Console.WriteLine($"  🌐 Searching: {query}");

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.Add("User-Agent",
            "ResearchAgent/1.0 (compatible; research bot)");

        var encoded = WebUtility.UrlEncode(query);
        // Use DuckDuckGo Instant Answer API (free, no key required)
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);

        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var sb = new StringBuilder();

        // Abstract / main answer
        var abstractText = root.GetProperty("AbstractText").GetString();
        var abstractSource = root.GetProperty("AbstractSource").GetString();
        var abstractUrl = root.GetProperty("AbstractURL").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            sb.AppendLine($"## {abstractSource}");
            sb.AppendLine(abstractText);
            sb.AppendLine($"Source: {abstractUrl}");
            sb.AppendLine();
        }

        // Related topics
        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            var count = 0;
            foreach (var item in topics.EnumerateArray())
            {
                if (count >= 8) break;
                var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var firstUrl = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                {
                    sb.AppendLine($"- {text}");
                    if (!string.IsNullOrWhiteSpace(firstUrl))
                        sb.AppendLine($"  URL: {firstUrl}");
                    count++;
                }
            }
        }

        var result = sb.ToString();
        return string.IsNullOrWhiteSpace(result)
            ? "No results found. Try a different query."
            : result;
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

// ---------------------------------------------------------------------------
// Notebook helper
// ---------------------------------------------------------------------------

/// <summary>Simple in-memory notebook for the agent to save and review findings.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save an important finding as a note. Use this to remember key facts.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved successfully.";
    }

    [Description("Read all saved notes. Use this to review findings before summarizing.")]
    public string ReadNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"Note #{i + 1}: {_notes[i]}");
        Console.WriteLine($"  📖 Reading {_notes.Count} note(s)");
        return sb.ToString();
    }
}

